contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= value, "insufficient test balance");

        uint balBefore = address(c).balance;
        uint countBefore = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdraw(value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balAfter = address(c).balance;
        uint countAfter = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool ownerWithdrewExpected = (balBefore >= value && balAfter == balBefore - value && countAfter == countBefore);
        bool revertCaseExpected = (balBefore < value && balAfter == balBefore && countAfter == countBefore);
        bool rule = (reverted && revertCaseExpected) || (!reverted && ownerWithdrewExpected);

        assert(rule);
    }

    receive() external payable {}
}

